1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { checkKxEligibility } from "@/lib/kx-eligibility";
4: import { z } from "zod";
5: 
6: export const dynamic = "force-dynamic";
7: 
8: const followSchema = z.object({
9:   targetType: z.enum(["POST", "TAG"]),
10:   targetId: z.string().min(1),
11: });
12: 
13: export async function GET(request: Request) {
14:   const eligibility = await checkKxEligibility(request);
15:   if (!eligibility) {
16:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
17:   }
18: 
19:   if (!eligibility.eligible) {
20:     return NextResponse.json(
21:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
22:       { status: 403 }
23:     );
24:   }
25: 
26:   const { searchParams } = new URL(request.url);
27:   const targetType = searchParams.get("targetType") as "POST" | "TAG" | null;
28:   const targetId = searchParams.get("targetId");
29: 
30:   if (!targetType || !targetId) {
31:     return NextResponse.json({ error: "targetType and targetId are required" }, { status: 400 });
32:   }
33: 
34:   const userId = eligibility.session.user.id;
35: 
36:   const follow = targetType === "POST"
37:     ? await db.kxFollow.findUnique({
38:         where: {
39:           userId_postId: { userId, postId: targetId },
40:         },
41:       })
42:     : await db.kxFollow.findUnique({
43:         where: {
44:           userId_tagId: { userId, tagId: targetId },
45:         },
46:       });
47: 
48:   return NextResponse.json({ isFollowing: !!follow });
49: }
