51: export async function POST(request: Request) {
52:   const eligibility = await checkKxEligibility(request);
53:   if (!eligibility) {
54:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
55:   }
56: 
57:   if (!eligibility.eligible) {
58:     return NextResponse.json(
59:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
60:       { status: 403 }
61:     );
62:   }
63: 
64:   try {
65:     const body = await request.json();
66:     const { targetType, targetId } = followSchema.parse(body);
67:     const userId = eligibility.session.user.id;
68: 
69:     if (targetType === "POST") {
70:       const post = await db.kxPost.findUnique({
71:         where: { id: targetId },
72:         select: { id: true, isDeleted: true },
73:       });
74:       if (!post || post.isDeleted) {
75:         return NextResponse.json({ error: "Post not found." }, { status: 404 });
76:       }
77: 
78:       const existing = await db.kxFollow.findUnique({
79:         where: {
80:           userId_postId: { userId, postId: targetId },
81:         },
82:       });
83: 
84:       if (existing) {
85:         await db.kxFollow.delete({ where: { id: existing.id } });
86:         return NextResponse.json({ isFollowing: false, action: "unfollowed" });
87:       } else {
88:         await db.kxFollow.create({
89:           data: {
90:             userId,
91:             postId: targetId,
92:           },
93:         });
94:         return NextResponse.json({ isFollowing: true, action: "followed" });
95:       }
96:     } else {
97:       const tag = await db.kxTag.findUnique({
98:         where: { id: targetId },
99:         select: { id: true },
100:       });
101:       if (!tag) {
102:         return NextResponse.json({ error: "Tag not found." }, { status: 404 });
103:       }
104: 
105:       const existing = await db.kxFollow.findUnique({
106:         where: {
107:           userId_tagId: { userId, tagId: targetId },
108:         },
109:       });
110: 
111:       if (existing) {
112:         await db.kxFollow.delete({ where: { id: existing.id } });
113:         return NextResponse.json({ isFollowing: false, action: "unfollowed" });
114:       } else {
115:         await db.kxFollow.create({
116:           data: {
117:             userId,
118:             tagId: targetId,
119:           },
120:         });
121:         return NextResponse.json({ isFollowing: true, action: "followed" });
122:       }
123:     }
124:   } catch (error) {
125:     if (error instanceof z.ZodError) {
126:       return NextResponse.json({ error: "Validation error", details: error.flatten() }, { status: 422 });
127:     }
128:     console.error("Error toggling follow:", error);
129:     return NextResponse.json({ error: "Internal server error" }, { status: 500 });
130:   }
131: }
