1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { checkKxEligibility } from "@/lib/kx-eligibility";
4: import { ModerationActionSchema } from "@/features/knowledge-exchange/schemas";
5: 
6: export const dynamic = "force-dynamic";
7: 
8: export async function POST(request: Request) {
9:   const eligibility = await checkKxEligibility(request);
10:   if (!eligibility) {
11:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
12:   }
13:   if (!eligibility.eligible) {
14:     return NextResponse.json(
15:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
16:       { status: 403 }
17:     );
18:   }
19: 
20:   // Restricted to PROFESSOR and ADMIN roles
21:   if (eligibility.role !== "ADMIN" && eligibility.role !== "INSTRUCTOR") {
22:     return NextResponse.json(
23:       { error: "Forbidden: Moderation actions are restricted to instructors and administrators." },
24:       { status: 403 }
25:     );
26:   }
27: 
28:   const json = await request.json().catch(() => null);
29:   const parsed = ModerationActionSchema.safeParse(json);
30:   if (!parsed.success) {
31:     return NextResponse.json(
32:       { error: parsed.error.issues[0]?.message || "Invalid input." },
33:       { status: 400 }
34:     );
35:   }
36: 
37:   const { targetType, targetId, actionType, reason, postId } = parsed.data;
38:   const moderatorId = eligibility.session.user.id;
39: 
40:   await db.$transaction(async (tx) => {
41:     // 1. Execute the action on the target model
42:     if (targetType === "POST") {
43:       switch (actionType) {
44:         case "CLOSE":
45:           await tx.kxPost.update({
46:             where: { id: targetId },
47:             data: { status: "CLOSED", closeReason: reason || "Closed by moderator" },
48:           });
49:           break;
50:         case "REOPEN":
51:           await tx.kxPost.update({
52:             where: { id: targetId },
53:             data: { status: "OPEN", closeReason: null },
54:           });
55:           break;
56:         case "LOCK":
57:           await tx.kxPost.update({
58:             where: { id: targetId },
59:             data: { status: "LOCKED" },
60:           });
61:           break;
62:         case "UNLOCK":
63:           await tx.kxPost.update({
64:             where: { id: targetId },
65:             data: { status: "OPEN" },
66:           });
67:           break;
68:         case "PIN":
69:           await tx.kxPost.update({
70:             where: { id: targetId },
71:             data: { isPinned: true },
72:           });
73:           break;
74:         case "UNPIN":
75:           await tx.kxPost.update({
76:             where: { id: targetId },
77:             data: { isPinned: false },
78:           });
79:           break;
80:         case "DELETE":
81:           await tx.kxPost.update({
82:             where: { id: targetId },
83:             data: { isDeleted: true },
84:           });
85:           break;
86:         case "RESTORE":
87:           await tx.kxPost.update({
88:             where: { id: targetId },
89:             data: { isDeleted: false },
90:           });
91:           break;
92:       }
93:     } else if (targetType === "ANSWER") {
94:       if (actionType === "DELETE") {
95:         await tx.kxAnswer.update({
96:           where: { id: targetId },
97:           data: { isDeleted: true },
98:         });
99:       } else if (actionType === "RESTORE") {
100:         await tx.kxAnswer.update({
101:           where: { id: targetId },
102:           data: { isDeleted: false },
103:         });
104:       }
105:     } else if (targetType === "COMMENT") {
106:       if (actionType === "DELETE") {
107:         await tx.kxComment.update({
108:           where: { id: targetId },
109:           data: { isDeleted: true },
110:         });
111:       } else if (actionType === "RESTORE") {
112:         await tx.kxComment.update({
113:           where: { id: targetId },
114:           data: { isDeleted: false },
115:         });
116:       }
117:     }
118: 
119:     // 2. Record immutable audit action in KxModerationAction
120:     await tx.kxModerationAction.create({
121:       data: {
122:         moderatorId,
123:         actionType,
124:         targetType,
125:         targetId,
126:         postId: postId || (targetType === "POST" ? targetId : null),
127:         reason: reason || "",
128:       },
129:     });
130: 
131:     // 3. Mark related flags as ACTIONED or REVIEWED
132:     if (targetType === "POST") {
133:       await tx.kxFlag.updateMany({
134:         where: { postId: targetId, status: "PENDING" },
135:         data: {
136:           status: "ACTIONED",
137:           reviewedById: moderatorId,
138:           reviewedAt: new Date(),
139:         },
140:       });
141:     } else if (targetType === "ANSWER") {
142:       await tx.kxFlag.updateMany({
143:         where: { answerId: targetId, status: "PENDING" },
144:         data: {
145:           status: "ACTIONED",
146:           reviewedById: moderatorId,
147:           reviewedAt: new Date(),
148:         },
149:       });
150:     }
151:   });
152: 
153:   return NextResponse.json({ success: true, message: `Action ${actionType} applied successfully.` });
154: }
