1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { checkKxEligibility } from "@/lib/kx-eligibility";
4: import { CreateAnswerSchema } from "@/features/knowledge-exchange/schemas";
5: import { serializeAuthor } from "@/features/knowledge-exchange/utils";
6: import { awardExpForAnswer } from "@/lib/gamification/kx-exp";
7: 
8: export const dynamic = "force-dynamic";
9: 
10: export async function POST(
11:   request: Request,
12:   { params }: { params: Promise<{ postId: string }> }
13: ) {
14:   const eligibility = await checkKxEligibility(request);
15:   if (!eligibility) {
16:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
17:   }
18:   if (!eligibility.eligible) {
19:     return NextResponse.json(
20:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
21:       { status: 403 }
22:     );
23:   }
24: 
25:   const { postId } = await params;
26:   const post = await db.kxPost.findUnique({
27:     where: { id: postId },
28:     select: { id: true, isDeleted: true, status: true, authorId: true, title: true },
29:   });
30: 
31:   if (!post || post.isDeleted) {
32:     return NextResponse.json({ error: "Post not found." }, { status: 404 });
33:   }
34: 
35:   if (post.status === "LOCKED") {
36:     return NextResponse.json(
37:       { error: "This post is locked. No new answers are allowed." },
38:       { status: 400 }
39:     );
40:   }
41: 
42:   const json = await request.json().catch(() => null);
43:   const parsed = CreateAnswerSchema.safeParse(json);
44:   if (!parsed.success) {
45:     return NextResponse.json(
46:       { error: parsed.error.issues[0]?.message || "Invalid input." },
47:       { status: 400 }
48:     );
49:   }
50: 
51:   const { body, isAnonymous } = parsed.data;
52:   const userId = eligibility.session.user.id;
53: 
54:   const answer = await db.$transaction(async (tx) => {
55:     const createdAnswer = await tx.kxAnswer.create({
56:       data: {
57:         postId,
58:         authorId: userId,
59:         body,
60:         isAnonymous,
61:       },
62:       include: {
63:         author: {
64:           select: {
65:             id: true,
66:             name: true,
67:             role: true,
68:             email: true,
69:             studentNumber: true,
70:             avatarUrl: true,
71:           },
72:         },
73:       },
74:     });
75: 
76:     await tx.kxPost.update({
77:       where: { id: postId },
78:       data: { answerCount: { increment: 1 } },
79:     });
80: 
81:     // Notify question author if not self
82:     if (post.authorId !== userId) {
83:       await tx.kxNotification.create({
84:         data: {
85:           userId: post.authorId,
86:           type: "ANSWER",
87:           title: "New Answer Received",
88:           message: `${isAnonymous ? "Someone" : eligibility.session.user.name} posted an answer to: "${post.title}"`,
89:           link: `/ics/knowledge-exchange/post/${postId}#answer-${createdAnswer.id}`,
90:         },
91:       });
92:     }
93: 
94:     return createdAnswer;
95:   });
96: 
97:   // Award EXP (+10 for answering)
98:   await awardExpForAnswer(userId, answer.id).catch(() => {});
99: 
100:   const viewer = {
101:     id: userId,
102:     role: eligibility.role,
103:   };
104: 
105:   const serialized = {
106:     id: answer.id,
107:     postId: answer.postId,
108:     authorId: answer.isAnonymous && viewer.role !== "ADMIN" ? null : answer.authorId,
109:     body: answer.body,
110:     isAnonymous: answer.isAnonymous,
111:     isAccepted: answer.isAccepted,
112:     isVerified: answer.isVerified,
113:     verifiedById: answer.verifiedById,
114:     voteCount: answer.voteCount,
115:     userVote: 0,
116:     isDeleted: answer.isDeleted,
117:     createdAt: answer.createdAt.toISOString(),
118:     updatedAt: answer.updatedAt.toISOString(),
119:     author: serializeAuthor(answer.author, answer.isAnonymous, viewer),
120:     comments: [],
121:   };
122: 
123:   return NextResponse.json({ success: true, answer: serialized }, { status: 201 });
124: }
