24:   const { postId } = await params;
25: 
26:   // Increment viewCount
27:   await db.kxPost
28:     .update({
29:       where: { id: postId },
30:       data: { viewCount: { increment: 1 } },
31:     })
32:     .catch(() => {});
33: 
34:   const post = await db.kxPost.findUnique({
35:     where: { id: postId },
36:     include: {
37:       author: {
38:         select: {
39:           id: true,
40:           name: true,
41:           role: true,
42:           email: true,
43:           studentNumber: true,
44:           avatarUrl: true,
45:         },
46:       },
47:       tags: {
48:         include: { tag: true },
49:       },
50:       course: {
51:         select: { id: true, code: true, title: true },
52:       },
53:       syllabusItem: {
54:         select: { id: true, title: true, type: true, enableIntegrityMonitoring: true },
55:       },
56:       votes: {
57:         where: { userId: eligibility.session.user.id },
58:         select: { value: true },
59:       },
60:       bookmarks: {
61:         where: { userId: eligibility.session.user.id },
62:         select: { id: true },
63:       },
64:       comments: {
65:         where: { isDeleted: false, answerId: null },
66:         include: {
67:           author: {
68:             select: {
69:               id: true,
70:               name: true,
71:               role: true,
72:               email: true,
73:               studentNumber: true,
74:               avatarUrl: true,
75:             },
76:           },
77:         },
78:         orderBy: { createdAt: "asc" },
79:       },
80:       answers: {
81:         where: { isDeleted: false },
82:         include: {
83:           author: {
84:             select: {
85:               id: true,
86:               name: true,
87:               role: true,
88:               email: true,
89:               studentNumber: true,
90:               avatarUrl: true,
91:             },
92:           },
93:           verifiedBy: {
94:             select: {
95:               id: true,
96:               name: true,
97:               role: true,
98:             },
99:           },
100:           votes: {
101:             where: { userId: eligibility.session.user.id },
102:             select: { value: true },
103:           },
104:           comments: {
105:             where: { isDeleted: false },
106:             include: {
107:               author: {
108:                 select: {
109:                   id: true,
110:                   name: true,
111:                   role: true,
112:                   email: true,
113:                   studentNumber: true,
114:                   avatarUrl: true,
115:                 },
116:               },
117:             },
118:             orderBy: { createdAt: "asc" },
119:           },
120:         },
121:         orderBy: [{ isAccepted: "desc" }, { voteCount: "desc" }, { createdAt: "asc" }],
122:       },
123:     },
124:   });
125: 
126:   if (!post || post.isDeleted) {
127:     return NextResponse.json({ error: "Post not found." }, { status: 404 });
128:   }
129: 
130:   const viewer = {
131:     id: eligibility.session.user.id,
132:     role: eligibility.role,
133:   };
134:   const isViewerAdmin = viewer.role === "ADMIN";
135: 
136:   const serializedAnswers = post.answers.map((a) => {
137:     const userVote = a.votes[0]?.value || 0;
138:     return {
139:       id: a.id,
140:       postId: a.postId,
141:       authorId: a.isAnonymous && !isViewerAdmin ? null : a.authorId,
142:       body: a.body,
143:       isAnonymous: a.isAnonymous,
144:       isAccepted: a.isAccepted,
145:       isVerified: a.isVerified,
146:       verifiedById: a.verifiedById,
147:       verifiedBy: a.verifiedBy,
148:       voteCount: a.voteCount,
149:       userVote,
150:       isDeleted: a.isDeleted,
151:       createdAt: a.createdAt.toISOString(),
152:       updatedAt: a.updatedAt.toISOString(),
153:       author: serializeAuthor(a.author, a.isAnonymous, viewer),
154:       comments: a.comments.map((c) => ({
155:         id: c.id,
156:         postId: c.postId,
157:         answerId: c.answerId,
158:         authorId: c.isAnonymous && !isViewerAdmin ? null : c.authorId,
159:         body: c.body,
160:         isAnonymous: c.isAnonymous,
161:         isDeleted: c.isDeleted,
162:         createdAt: c.createdAt.toISOString(),
163:         updatedAt: c.updatedAt.toISOString(),
164:         author: serializeAuthor(c.author, c.isAnonymous, viewer),
165:       })),
166:     };
167:   });
168: 
169:   const serializedPost = {
170:     id: post.id,
171:     title: post.title,
172:     body: post.body,
173:     postType: post.postType,
174:     status: post.status,
175:     isAnonymous: post.isAnonymous,
176:     authorId: post.isAnonymous && !isViewerAdmin ? null : post.authorId,
177:     instituteId: post.instituteId,
178:     courseId: post.courseId,
179:     syllabusItemId: post.syllabusItemId,
180:     viewCount: post.viewCount,
181:     voteCount: post.voteCount,
182:     answerCount: post.answerCount,
183:     isPinned: post.isPinned,
184:     isDeleted: post.isDeleted,
185:     closeReason: post.closeReason,
186:     createdAt: post.createdAt.toISOString(),
187:     updatedAt: post.updatedAt.toISOString(),
188:     userVote: post.votes[0]?.value || 0,
189:     isBookmarked: post.bookmarks.length > 0,
190:     author: serializeAuthor(post.author, post.isAnonymous, viewer),
191:     tags: post.tags.map((pt) => ({
192:       id: pt.tag.id,
193:       name: pt.tag.name,
194:       slug: pt.tag.slug,
195:       description: pt.tag.description,
196:       category: pt.tag.category,
197:       postCount: pt.tag.postCount,
198:     })),
199:     course: post.course,
200:     syllabusItem: post.syllabusItem,
201:     comments: post.comments.map((c) => ({
202:       id: c.id,
203:       postId: c.postId,
204:       answerId: c.answerId,
205:       authorId: c.isAnonymous && !isViewerAdmin ? null : c.authorId,
206:       body: c.body,
207:       isAnonymous: c.isAnonymous,
208:       isDeleted: c.isDeleted,
209:       createdAt: c.createdAt.toISOString(),
210:       updatedAt: c.updatedAt.toISOString(),
211:       author: serializeAuthor(c.author, c.isAnonymous, viewer),
212:     })),
213:     answers: serializedAnswers,
214:   };
215: 
216:   return NextResponse.json({ post: serializedPost });
217: }
