219: export async function PATCH(
220:   request: Request,
221:   { params }: { params: Promise<{ postId: string }> }
222: ) {
223:   const eligibility = await checkKxEligibility(request);
224:   if (!eligibility) {
225:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
226:   }
227:   if (!eligibility.eligible) {
228:     return NextResponse.json(
229:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
230:       { status: 403 }
231:     );
232:   }
233: 
234:   const { postId } = await params;
235:   const post = await db.kxPost.findUnique({ where: { id: postId } });
236:   if (!post || post.isDeleted) {
237:     return NextResponse.json({ error: "Post not found." }, { status: 404 });
238:   }
239: 
240:   const isAuthor = post.authorId === eligibility.session.user.id;
241: 
242:   if (!isAuthor) {
243:     return NextResponse.json(
244:       { error: "Forbidden: Only the original author can edit this post." },
245:       { status: 403 }
246:     );
247:   }
248: 
249:   const json = await request.json().catch(() => null);
250:   const parsed = UpdatePostSchema.safeParse(json);
251:   if (!parsed.success) {
252:     return NextResponse.json(
253:       { error: parsed.error.issues[0]?.message || "Invalid input." },
254:       { status: 400 }
255:     );
256:   }
257: 
258:   const { title, body, summary, tagIds } = parsed.data;
259: 
260:   const updatedPost = await db.$transaction(async (tx) => {
261:     // Record revision
262:     await tx.kxRevision.create({
263:       data: {
264:         postId,
265:         editorId: eligibility.session.user.id,
266:         title: title || post.title,
267:         body: body || post.body,
268:         summary: summary || "Post updated",
269:       },
270:     });
271: 
272:     // Update tags if provided
273:     if (tagIds) {
274:       await tx.kxPostTag.deleteMany({ where: { postId } });
275:       for (const tagId of tagIds) {
276:         await tx.kxPostTag.create({
277:           data: { postId, tagId },
278:         });
279:       }
280:     }
281: 
282:     // Update post record
283:     return await tx.kxPost.update({
284:       where: { id: postId },
285:       data: {
286:         title: title ?? undefined,
287:         body: body ?? undefined,
288:       },
289:     });
290:   });
291: 
292:   return NextResponse.json({ success: true, post: updatedPost });
293: }
