295: export async function DELETE(
296:   request: Request,
297:   { params }: { params: Promise<{ postId: string }> }
298: ) {
299:   const eligibility = await checkKxEligibility(request);
300:   if (!eligibility) {
301:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
302:   }
303:   if (!eligibility.eligible) {
304:     return NextResponse.json(
305:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
306:       { status: 403 }
307:     );
308:   }
309: 
310:   const { postId } = await params;
311:   const post = await db.kxPost.findUnique({ where: { id: postId } });
312:   if (!post) {
313:     return NextResponse.json({ error: "Post not found." }, { status: 404 });
314:   }
315: 
316:   const role = (eligibility.role || "").toUpperCase();
317:   const isAuthor = post.authorId === eligibility.session.user.id;
318:   const isStaff = role === "ADMIN" || role === "INSTRUCTOR";
319: 
320:   if (!isAuthor && !isStaff) {
321:     return NextResponse.json(
322:       { error: "Forbidden: You do not have permission to delete this post." },
323:       { status: 403 }
324:     );
325:   }
326: 
327:   // Soft delete
328:   await db.kxPost.update({
329:     where: { id: postId },
330:     data: { isDeleted: true },
331:   });
332: 
333:   return NextResponse.json({ success: true, message: "Post deleted." });
334: }
