1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { checkKxEligibility } from "@/lib/kx-eligibility";
4: import { CreatePostSchema } from "@/features/knowledge-exchange/schemas";
5: import { serializeAuthor } from "@/features/knowledge-exchange/utils";
6: import { awardExpForQuestion } from "@/lib/gamification/kx-exp";
7: import { KX_FEED_PAGE_SIZE } from "@/features/knowledge-exchange/constants";
8: import type { Prisma } from "@prisma/client";
9: 
10: export const dynamic = "force-dynamic";
11: 
12: export async function GET(request: Request) {
13:   const eligibility = await checkKxEligibility(request);
14:   if (!eligibility) {
15:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
16:   }
17:   if (!eligibility.eligible) {
18:     return NextResponse.json(
19:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
20:       { status: 403 }
21:     );
22:   }
23: 
24:   const { searchParams } = new URL(request.url);
25:   const tab = searchParams.get("tab") || "all";
26:   const sort = searchParams.get("sort") || "newest";
27:   const search = searchParams.get("search")?.trim();
28:   const tag = searchParams.get("tag")?.trim();
29:   const courseId = searchParams.get("courseId")?.trim();
30:   const page = Math.max(1, parseInt(searchParams.get("page") || "1", 10));
31:   const limit = Math.min(
32:     50,
33:     Math.max(1, parseInt(searchParams.get("limit") || String(KX_FEED_PAGE_SIZE), 10))
34:   );
35:   const skip = (page - 1) * limit;
36: 
37:   // Build where clause
38:   const where: Prisma.KxPostWhereInput = {
39:     isDeleted: false,
40:   };
41: 
42:   // Institute scoping: get the institute ID for ICS
43:   const institute = await db.institute.findUnique({
44:     where: { code: "ics" },
45:     select: { id: true },
46:   });
47:   if (institute) {
48:     where.instituteId = institute.id;
49:   }
50: 
51:   // Tab filtering
52:   if (tab === "unanswered") {
53:     where.answerCount = 0;
54:     where.status = "OPEN";
55:   } else if (tab === "answered") {
56:     where.status = "ANSWERED";
57:   } else if (tab === "discussions") {
58:     where.postType = "DISCUSSION";
59:   } else if (tab === "my-posts") {
60:     where.authorId = eligibility.session.user.id;
61:   }
62: 
63:   // Course filtering
64:   if (courseId) {
65:     where.courseId = courseId;
66:   }
67: 
68:   // Tag filtering
69:   if (tag) {
70:     where.tags = {
71:       some: {
72:         tag: {
73:           slug: tag.toLowerCase(),
74:         },
75:       },
76:     };
77:   }
78: 
79:   // Full-text search across title and body
80:   if (search) {
81:     where.OR = [
82:       { title: { contains: search, mode: "insensitive" } },
83:       { body: { contains: search, mode: "insensitive" } },
84:     ];
85:   }
86: 
87:   // Sorting
88:   let orderBy: Prisma.KxPostOrderByWithRelationInput[] = [{ isPinned: "desc" }];
89:   if (sort === "votes") {
90:     orderBy.push({ voteCount: "desc" }, { createdAt: "desc" });
91:   } else if (sort === "active") {
92:     orderBy.push({ updatedAt: "desc" });
93:   } else {
94:     // Default newest
95:     orderBy.push({ createdAt: "desc" });
96:   }
97: 
98:   const [posts, totalCount] = await Promise.all([
99:     db.kxPost.findMany({
100:       where,
101:       include: {
102:         author: {
103:           select: {
104:             id: true,
105:             name: true,
106:             role: true,
107:             email: true,
108:             studentNumber: true,
109:             avatarUrl: true,
110:           },
111:         },
112:         tags: {
113:           include: { tag: true },
114:         },
115:         course: {
116:           select: { id: true, code: true, title: true },
117:         },
118:         syllabusItem: {
119:           select: { id: true, title: true, type: true, enableIntegrityMonitoring: true },
120:         },
121:         votes: {
122:           where: { userId: eligibility.session.user.id },
123:           select: { value: true },
124:         },
125:         bookmarks: {
126:           where: { userId: eligibility.session.user.id },
127:           select: { id: true },
128:         },
129:         answers: {
130:           where: { isDeleted: false },
131:           orderBy: [
132:             { isAccepted: "desc" },
133:             { isVerified: "desc" },
134:             { voteCount: "desc" },
135:             { createdAt: "asc" },
136:           ],
137:           take: 1,
138:           include: {
139:             author: {
140:               select: {
141:                 id: true,
142:                 name: true,
143:                 role: true,
144:                 email: true,
145:                 studentNumber: true,
146:                 avatarUrl: true,
147:               },
148:             },
149:           },
150:         },
151:         comments: {
152:           where: { isDeleted: false, answerId: null },
153:           orderBy: { createdAt: "asc" },
154:           take: 1,
155:           include: {
156:             author: {
157:               select: {
158:                 id: true,
159:                 name: true,
160:                 role: true,
161:                 email: true,
162:                 studentNumber: true,
163:                 avatarUrl: true,
164:               },
165:             },
166:           },
167:         },
168:       },
169:       orderBy,
170:       skip,
171:       take: limit,
172:     }),
173:     db.kxPost.count({ where }),
174:   ]);
175: 
176:   const viewer = {
177:     id: eligibility.session.user.id,
178:     role: eligibility.role,
179:   };
180:   const isViewerAdmin = viewer.role === "ADMIN";
181: 
182:   const serializedPosts = posts.map((p) => {
183:     const userVote = p.votes[0]?.value || 0;
184:     const isBookmarked = p.bookmarks.length > 0;
185: 
186:     const topAnswerRaw = p.answers?.[0];
187:     const topAnswer = topAnswerRaw
188:       ? {
189:           id: topAnswerRaw.id,
190:           body: topAnswerRaw.body,
191:           isAccepted: topAnswerRaw.isAccepted,
192:           isVerified: topAnswerRaw.isVerified,
193:           voteCount: topAnswerRaw.voteCount,
194:           createdAt: topAnswerRaw.createdAt.toISOString(),
195:           author: serializeAuthor(topAnswerRaw.author, topAnswerRaw.isAnonymous, viewer),
196:         }
197:       : null;
198: 
199:     const topCommentRaw = !topAnswer && p.comments?.[0];
200:     const topComment = topCommentRaw
201:       ? {
202:           id: topCommentRaw.id,
203:           body: topCommentRaw.body,
204:           createdAt: topCommentRaw.createdAt.toISOString(),
205:           author: serializeAuthor(topCommentRaw.author, topCommentRaw.isAnonymous, viewer),
206:         }
207:       : null;
208: 
209:     return {
210:       id: p.id,
211:       title: p.title,
212:       body: p.body,
213:       postType: p.postType,
214:       status: p.status,
215:       isAnonymous: p.isAnonymous,
216:       authorId: p.isAnonymous && !isViewerAdmin ? null : p.authorId,
217:       instituteId: p.instituteId,
218:       courseId: p.courseId,
219:       syllabusItemId: p.syllabusItemId,
220:       viewCount: p.viewCount,
221:       voteCount: p.voteCount,
222:       answerCount: p.answerCount,
223:       isPinned: p.isPinned,
224:       isDeleted: p.isDeleted,
225:       closeReason: p.closeReason,
226:       createdAt: p.createdAt.toISOString(),
227:       updatedAt: p.updatedAt.toISOString(),
228:       userVote,
229:       isBookmarked,
230:       topAnswer,
231:       topComment,
232:       author: serializeAuthor(p.author, p.isAnonymous, viewer),
233:       tags: p.tags.map((pt) => ({
234:         id: pt.tag.id,
235:         name: pt.tag.name,
236:         slug: pt.tag.slug,
237:         description: pt.tag.description,
238:         category: pt.tag.category,
239:         postCount: pt.tag.postCount,
240:       })),
241:       course: p.course,
242:       syllabusItem: p.syllabusItem,
243:     };
244:   });
245: 
246:   return NextResponse.json({
247:     posts: serializedPosts,
248:     pagination: {
249:       page,
250:       limit,
251:       totalCount,
252:       totalPages: Math.ceil(totalCount / limit),
253:     },
254:   });
255: }
