257: export async function POST(request: Request) {
258:   const eligibility = await checkKxEligibility(request);
259:   if (!eligibility) {
260:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
261:   }
262:   if (!eligibility.eligible) {
263:     return NextResponse.json(
264:       { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
265:       { status: 403 }
266:     );
267:   }
268: 
269:   const json = await request.json().catch(() => null);
270:   const parsed = CreatePostSchema.safeParse(json);
271:   if (!parsed.success) {
272:     return NextResponse.json(
273:       { error: parsed.error.issues[0]?.message || "Invalid input." },
274:       { status: 400 }
275:     );
276:   }
277: 
278:   const { title, body, postType, isAnonymous, tagIds, courseId, syllabusItemId } =
279:     parsed.data;
280: 
281:   const institute = await db.institute.findUnique({
282:     where: { code: "ics" },
283:     select: { id: true },
284:   });
285: 
286:   if (!institute) {
287:     return NextResponse.json(
288:       { error: "Institute of Computer Studies not found." },
289:       { status: 500 }
290:     );
291:   }
292: 
293:   const userId = eligibility.session.user.id;
294: 
295:   // Execute in transaction
296:   const createdPost = await db.$transaction(async (tx) => {
297:     const newPost = await tx.kxPost.create({
298:       data: {
299:         title,
300:         body,
301:         postType,
302:         isAnonymous,
303:         authorId: userId,
304:         instituteId: institute.id,
305:         courseId: courseId || null,
306:         syllabusItemId: syllabusItemId || null,
307:       },
308:     });
309: 
310:     // Link tags
311:     if (tagIds.length > 0) {
312:       for (const tagId of tagIds) {
313:         await tx.kxPostTag.create({
314:           data: {
315:             postId: newPost.id,
316:             tagId,
317:           },
318:         });
319:         await tx.kxTag.update({
320:           where: { id: tagId },
321:           data: { postCount: { increment: 1 } },
322:         });
323:       }
324:     }
325: 
326:     return newPost;
327:   });
328: 
329:   // Award EXP (+5 for asking/starting post)
330:   await awardExpForQuestion(userId, createdPost.id).catch(() => {});
331: 
332:   return NextResponse.json({ success: true, post: createdPost }, { status: 201 });
333: }
